mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM devlog_tag
    WHERE id = #{id}
      AND name = #{name}
)

SELECT DISTINCT n.name FROM (
SELECT #{name} AS name
) n LEFT JOIN devlog_tag t ON t.name = n.name WHERE t.id IS NULL
